function _regroup3x3(address from, address to, uint256 x, uint256 y, bool set) internal returns (bool) {
    uint256 id = x + y * GRID_SIZE;
    uint256 quadId = LAYER_3x3 + id;
    bool ownerOfAll = true;
    for (uint256 xi = x; xi < x+3; xi++) {
        for (uint256 yi = y; yi < y+3; yi++) {
            ownerOfAll = _checkAndClear(from, xi + yi * GRID_SIZE) && ownerOfAll;
        }
    }
    if(set) {
        if(!ownerOfAll) {
            require( _owners[quadId] == uint256(from) || _owners[LAYER_6x6 + (x/6) * 6 + ((y/6) * 6) * GRID_SIZE] == uint256(from) || _owners[LAYER_12x12 + (x/12) * 12 + ((y/12) * 12) * GRID_SIZE] == uint256(from) || _owners[LAYER_24x24 + (x/24) * 24 + ((y/24) * 24) * GRID_SIZE] == uint256(from), "not owner of all sub quads nor parent quads" );
        }
        _owners[quadId] = uint256(to);
        return true;
    }
    return ownerOfAll;
}

