    bool ownerOfAll = true;
    for (uint256 xi = x; xi < x+6; xi += 3) {
        for (uint256 yi = y; yi < y+6; yi += 3) {
            bool ownAllIndividual = _regroup3x3(from, to, xi, yi, false);
